def make_question(index, row):
    tag, prompt, options, answer, reason = row
    opts = [{"id": chr(65+i), "text": text} for i, text in enumerate(options)]
    aid = next(o["id"] for o in opts if o["text"] == answer)
    refs = [{"url": u, "title": f"{t}；僅研究公開題型與能力方向，未複製原題。", "year": "113-114", "subject": "social", "locator": l, "observedPattern": "公立學校社會科公開試題常見的海域、資源治理與公共議題資料推理能力，經本題重新設計。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for u,t,l in SOURCES]
    steps = [f"讀題定位：圈出「{tag}」的基線、距離、海域類型、資源、群體與制度條件。", f"整理證據：分開記錄地圖事實、法律權利、資源利用與環境結果；核心理由是「{reason}」。", f"核對正解：選項 {aid}「{answer}」同時符合海域空間與治理條件。", "排除誘答：檢查是否只看面積、船籍、總量或單一主張，並找出缺少的界線與規範。", "結論回查：確認距離、資料期間、權利內容與保育限制相互一致；情境改變時重新判讀。"]
    return {"id": f"question-social-content-geo-ab-iv-3-{index}", "subject": "social", "type": "single-choice", "prompt": prompt, "options": opts, "knowledgeIds": ["kg-social-content-geo-ab-iv-3"], "difficulty": "medium", "answer": {"value": aid, "explanation": reason}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "高雄市立鹽埕國中三年級社會科公開段考；本題只研究公開試題能力結構與資料型態。", "authoringNote": "依官方課綱、單元 KG 與三個公立學校公開來源的題型方向，獨立改寫臺灣領海與經濟海域情境；未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-09", "lessonId": "lesson-social-content-geo-ab-iv-3", "examPatternRefs": refs, "solutionStrategy": "先用基線與距離辨識海域，再區分主權、資源權利與管理限制，最後把地圖、制度與資源資料交叉檢核。", "solutionSteps": steps}

for index, row in enumerate(DATA, 1):
    (OUT / f"question-social-content-geo-ab-iv-3-{index}.json").write_text(json.dumps(make_question(index, row), ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
